stock=stock_at_target
future_lost=0
first_stockout=-1
for r in sorted(future,key=lambda r:(r["event_time"],r["event_id"])):
    if r["kind"]=="receipt":
        stock += r["quantity"]
    else:
        unmet=max(0,r["quantity"]-stock)
        if unmet>0 and first_stockout==-1:
            first_stockout=r["event_time"]
        future_lost += unmet
        stock -= min(stock,r["quantity"])
stock, future_lost, first_stockout
